1	export type Cell = [number, number];
2	
3	function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return (
5	    Math.abs(x - otherX) <= 1 &&
6	    Math.abs(y - otherY) <= 1 &&
7	    !(x === otherX && y === otherY)
8	  );
9	}
10	
11	function countLiveNeighbors(cell: Cell, cells: Cell[]): number {
12	  return cells.filter((other) => isNeighbor(cell, other)).length;
13	}
14	
15	export function nextGeneration(cells: Cell[]): Cell[] {
16	  return cells.filter((cell) => {
17	    const liveNeighbors = countLiveNeighbors(cell, cells);
18	    return liveNeighbors === 2 || liveNeighbors === 3;
19	  });
20	}
